def esc(value):
    return html.escape(str(value), quote=True)

def svg_chart(kind, prefix):
    w, h, left, right, top, bottom = 440, 260, 38, 14, 25, 35
    iw, ih = w-left-right, h-top-bottom
    prefix += "-chart"
    parts = [f'<svg class="chart" viewBox="0 0 {w} {h}" role="img" aria-labelledby="{prefix}-title {prefix}-desc">']
    if kind == "demand":
        parts += [f'<title id="{prefix}-title">Observed and modeled hourly bike demand</title>', f'<desc id="{prefix}-desc">Average hourly rentals in the October to December 2012 holdout. A morning peak and a larger evening peak are visible. The modeled profile follows both.</desc>']
        ymax = 600
        for v in [0, 200, 400, 600]:
            y = top + ih * (1-v/ymax)
            parts.append(f'<line class="grid" x1="{left}" x2="{w-right}" y1="{y}" y2="{y}"/><text x="{left-8}" y="{y+4}" text-anchor="end">{v}</text>')
        for hr in [0, 6, 12, 18, 23]:
            x=left+iw*hr/23
            parts.append(f'<text x="{x}" y="{h-12}" text-anchor="middle">{hr:02d}:00</text>')
        for key, style in [("cnt", "actual"), ("prediction", "model")]:
            points = " ".join(f'{left+iw*r["hr"]/23:.2f},{top+ih*(1-r[key]/ymax):.2f}' for r in D["hourly_profile"])
            parts.append(f'<polyline class="{style}" points="{points}"/>')
    elif kind == "campaign":
        parts += [f'<title id="{prefix}-title">Cumulative response gains</title>', f'<desc id="{prefix}-desc">Selecting the highest-scoring 20 percent of holdout contacts captures 39 percent of observed responses. The diagonal represents random targeting.</desc>']
        for v in [0,25,50,75,100]:
            y=top+ih*(1-v/100)
            x=left+iw*v/100
            parts.append(f'<line class="grid" x1="{left}" x2="{w-right}" y1="{y}" y2="{y}"/><text x="{left-8}" y="{y+4}" text-anchor="end">{v}%</text><text x="{x}" y="{h-12}" text-anchor="middle">{v}%</text>')
        parts.append(f'<line class="baseline" x1="{left}" x2="{w-right}" y1="{h-bottom}" y2="{top}"/>')
        points = f'{left},{h-bottom} ' + " ".join(f'{left+iw*r["budget_pct"]/100:.2f},{top+ih*(1-r["recall"]):.2f}' for r in C["budgets"])
        parts.append(f'<polyline class="actual" points="{points}"/>')
        x,y=left+iw*.2,top+ih*(1-C["top_20"]["recall"])
        parts.append(f'<circle cx="{x}" cy="{y}" r="5" fill="#b96743"/><text x="{x+10}" y="{y-13}">20% of contacts</text>')
    else:
        parts += [f'<title id="{prefix}-title">Two customer groups in spending space</title>', f'<desc id="{prefix}-desc">Two-dimensional principal component projection of 440 customer spend profiles. Green and terracotta show the two clusters. The projection retains 71.3 percent of variance; clusters overlap.</desc>']
        pts=S["projection"]
        xmin,xmax=min(p["x"] for p in pts)-.4,max(p["x"] for p in pts)+.4
        ymin,ymax=min(p["y"] for p in pts)-.4,max(p["y"] for p in pts)+.4
        for t in [.25,.5,.75]:
            y=top+ih*t
            parts.append(f'<line class="grid" x1="{left}" x2="{w-right}" y1="{y}" y2="{y}"/>')
        for p in pts:
            x=left+iw*(p["x"]-xmin)/(xmax-xmin)
            y=top+ih*(1-(p["y"]-ymin)/(ymax-ymin))
            fill=["#28684f","#b96743"][p["segment"]]
            parts.append(f'<circle cx="{x:.2f}" cy="{y:.2f}" r="2.7" fill="{fill}" opacity=".53"/>')
        parts.append(f'<text x="{left+iw/2}" y="{h-12}" text-anchor="middle">Principal component 1</text><text transform="translate(12 {top+ih/2}) rotate(-90)" text-anchor="middle">Principal component 2</text>')
    return "".join(parts)+"</svg>"

